import (
	"context"
	_ "embed"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	craftevents "github.com/craftgodotdev/craftgo/pkg/events"
	"github.com/craftgodotdev/craftgo/pkg/events/codecjson"
	"github.com/craftgodotdev/craftgo/pkg/events/logging"
	"github.com/craftgodotdev/craftgo/pkg/events/memory"
	"github.com/craftgodotdev/craftgo/pkg/log"
	"github.com/craftgodotdev/craftgo/pkg/server"
	"github.com/craftgodotdev/craftgo/pkg/telemetry"

	"github.com/craftgodotdev/craftgo/example/taskflow/config"
	"github.com/craftgodotdev/craftgo/example/taskflow/internal/activity"
	"github.com/craftgodotdev/craftgo/example/taskflow/internal/middleware"
	"github.com/craftgodotdev/craftgo/example/taskflow/internal/wiring"
	"github.com/craftgodotdev/craftgo/example/taskflow/svccontext"
)

// openapiSpec is the generated OpenAPI document the docs page serves.
//
//go:embed docs/openapi.yaml
var openapiSpec []byte

func main() {
	// Container healthcheck mode (`taskflow -healthcheck`): probe our own
	// /readyz and exit 0/1. Lets the distroless image self-check without a
	// shell or curl (see docker-compose.yml).
	if len(os.Args) > 1 && os.Args[1] == "-healthcheck" {
		resp, err := http.Get("http://127.0.0.1:8080/readyz")
		if err != nil || resp.StatusCode != http.StatusOK {
			os.Exit(1)
		}
		os.Exit(0)
	}

	cfg, err := config.Load(config.Path())
	if err != nil {
		log.Default().Error("load config", log.Err(err))
		os.Exit(1)
	}

	// An unrecognised logging.level keeps the info default.
	if lvl, ok := log.ParseLevel(cfg.Logging.Level); ok {
		log.SetLevel(lvl)
	}

	ctx := context.Background()
	tel, err := telemetry.Init(ctx, cfg.Config)
	if err != nil {
		log.Default().Error("init telemetry", log.Err(err))
		os.Exit(1)
	}
	if url := tel.ScrapeURL(); url != "" {
		log.Default().Info("metrics scrape listening", log.String("url", url))
	}
	if errCh := tel.AdminErr(); errCh != nil {
		go func() {
			if err := <-errCh; err != nil {
				log.Default().Error("metrics scrape listener", log.Err(err))
			}
		}()
	}

	svc := svccontext.NewServiceContext(cfg)

	// The event bus binds one transport to one codec. This build uses the
	// in-process transport so publishes and consumers run in one binary;
	// pointing it at Kafka, NATS, RabbitMQ or SQS is a change to these
	// three lines and nothing else - no generated file mentions a broker.
	bus := craftevents.New(
		craftevents.WithTransport(memory.New()),
		craftevents.WithCodec(codecjson.Codec{}),
	)
	// One line per delivery: the contract, the listener, the key, how long
	// it took, and the error when there was one. The chain goes on the BUS,
	// so it covers every subscription registered through it and no module
	// has to be handed one.
	bus.Use(logging.AccessLog(log.Slog()))
	svc.Bus = bus

	// The design declares which contracts exist; this binary says which
	// of them it listens to and under what group. Registration records
	// the subscriptions; Start hands the whole batch to the transport at
	// once, because a broker that binds one identity to several contracts
	// cannot register a group one contract at a time.
	if err := activity.Register(bus, svc.Activity); err != nil {
		log.Default().Error("register consumers", log.Err(err))
		os.Exit(1)
	}
	deliver, stopDelivery := context.WithCancel(ctx)
	defer stopDelivery()
	if err := bus.Start(deliver); err != nil {
		log.Default().Error("start consumers", log.Err(err))
		os.Exit(1)
	}

	// Each middleware the design declares is a field of svc, assigned once here.
	svc.AccessLog = middleware.NewAccessLogMiddleware()
	svc.AdminOnly = middleware.NewAdminOnlyMiddleware()
	svc.AuthRequired = middleware.NewAuthRequiredMiddleware()
	svc.RateLimit = middleware.NewRateLimitMiddleware()
	svc.RequestID = middleware.NewRequestIDMiddleware()

	// The telemetry wrapper opens each request's span outside Recovery and every Use
	// middleware, so the access and panic lines carry its trace ids.
	srv := server.New(svc, server.WithTelemetry(tel.HTTPMiddleware()))
	srv.Use(server.AccessLog(log.Follow()))
	// A method's @timeout or @maxBodySize overrides these defaults; routes resolve them
	// when wiring.Register registers them.
	srv.SetDefaultHandlerTimeout(cfg.Server.HandlerTimeout)
	srv.SetDefaultMaxBodySize(cfg.Server.MaxBodySize)
	if err := srv.SetStrictJSON(cfg.Server.StrictJSON); err != nil {
		log.Default().Error("strict json", log.Err(err))
		os.Exit(1)
	}
	// Readiness probe: /readyz flips to 503 if the store is unreachable. A
	// Postgres-backed store pings the pool here; the in-memory store is always
	// ready. Orchestrators (Kubernetes, compose healthchecks) poll this.
	srv.RegisterHealthCheck("store", 2*time.Second, func(context.Context) error {
		return svc.Store.Ping()
	})

	if cfg.Server.Compression.Enabled {
		srv.Use(server.Compress(server.CompressOptions{
			MinSize: cfg.Server.Compression.MinSize,
			Level:   cfg.Server.Compression.Level,
		}))
	}

	// wiring is regenerated on each craftgo gen and registers every HTTP route the design
	// declares.
	shutdownWiring, err := wiring.Register(ctx, srv, svc)
	if err != nil {
		log.Default().Error("wire services", log.Err(err))
		os.Exit(1)
	}

	// The docs page loads its UI assets from a CDN.
	if cfg.Docs.Enabled {
		srv.ServeDocs(server.DocsOptions{
			Spec:     openapiSpec,
			UI:       cfg.Docs.UI,
			Path:     cfg.Docs.Path,
			SpecPath: cfg.Docs.SpecPath,
		})
	}

	go func() {
		log.Default().Info("listening", log.String("addr", cfg.Server.Addr))
		if err := srv.Start(cfg.Server.Addr); err != nil {
			log.Default().Error("server start", log.Err(err))
			os.Exit(1)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	// Every listener drains, and every wiring shutdown runs, within one budget.
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = srv.Stop(shutdownCtx)
	// Consumers stop taking new messages; the in-flight ones finish on
	// the transport's own terms.
	stopDelivery()
	_ = shutdownWiring(shutdownCtx)
	// Shutdown closes the scrape listener and flushes any pending OTLP batch.
	if err := tel.Shutdown(shutdownCtx); err != nil {
		log.Default().Error("shutdown telemetry", log.Err(err))
	}
}
